 const participants=(state.data.trainingParticipants||[]).map(x=>`<tr><td>${person(x.employee_name||"Employee")}</td><td>${esc(x.programme_title||"Programme")}</td><td>${badge(x.attendance_status||"Registered")}</td><td>${badge(x.completion_status||"Pending")}</td><td>${canManage?`<button class="row-actions" data-action="participant-status" data-id="${esc(x.id)}">Update</button>`:x.attendance_status==="Attended"?`<button class="row-actions" data-action="training-evaluation" data-id="${esc(x.id)}">Evaluate</button>`:"—"}</td></tr>`).join("");
 const evaluations=(state.data.trainingEvaluations||[]).map(x=>`<tr><td>${person(x.employee_name)}</td><td>${esc(x.programme_title)}</td><td>${x.pre_score??"—"}</td><td>${x.post_score??"—"}</td><td>${x.effectiveness_score??"—"}</td><td>${fmtDate(String(x.evaluated_at||"").slice(0,10))}</td></tr>`).join("");
 const actions=`${canSubmit?`<button class="btn btn-outline" data-action="add-training">＋ Training need</button>`:""}${canManage?`<button class="btn btn-primary" data-action="add-programme">＋ Create programme</button>`:""}`;
 return `${pageHeader("Training & development","Manage skill gaps, training programmes, enrolment, completion and evaluation.",actions)}<div class="stats-grid">${stat("Training needs",(state.data.training||[]).length,"Employee requests and HR needs","◎")}${stat("Programmes",(state.data.trainingProgrammes||[]).length,"Scheduled training","▧")}${stat("Participants",(state.data.trainingParticipants||[]).length,"Enrolled employees","♙")}${stat("Pending requests",(state.data.training||[]).filter(x=>x.status==="Pending").length,"Awaiting review","◷")}</div><div class="panel"><div class="panel-head"><h4>Training needs and requests</h4></div>${table(["Employee","Training need","Category","Requested start","Status","Reason","Decision"],needs,"No training needs recorded.")}</div><div class="panel"><div class="panel-head"><h4>Training programmes</h4></div>${table(["Programme","Schedule","Budget","Status","Enrolment"],programmes,"No programmes created.")}</div><div class="panel"><div class="panel-head"><h4>Programme participants</h4></div>${table(["Employee","Programme","Attendance","Completion","Action"],participants,"No participants enrolled.")}</div><div class="panel"><div class="panel-head"><h4>Training evaluations</h4></div>${table(["Employee","Programme","Pre-score","Post-score","Effectiveness","Evaluated"],evaluations,"No post-training evaluations.")}</div>`;
