function performance(){
 const role=state.profile?.role,canManage=["administrator","hr","manager"].includes(role)||isDemo,isHr=["administrator","hr"].includes(role)||isDemo;
 const periods=(state.data.appraisalPeriods||[]).map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${fmtDate(x.start_date)} – ${fmtDate(x.end_date)}</td><td>${badge(x.status)}</td></tr>`).join("");
 const criteria=(state.data.appraisalCriteria||[]).filter(x=>x.active!==false).map(x=>`<tr><td>${esc(x.name)}</td><td>${Number(x.weight||1)}%</td><td>${badge(x.active===false?"Inactive":"Active")}</td></tr>`).join("");
 const appraisals=(state.data.appraisals||[]).map(x=>`<tr><td>${person(x.employee_name||"Employee")}</td><td>${esc(x.period_name||"—")}</td><td>${x.overall_score==null?"—":Number(x.overall_score).toFixed(2)+" / 5"}</td><td>${badge(x.status)}</td><td>${isHr||x.manager_id===state.user?.id||isDemo?`<button class="row-actions" data-action="score-appraisal" data-id="${esc(x.id)}">${x.status==="Finalized"?"View scores":"Score / review"}</button>`:"—"}${(isHr||x.manager_id===state.user?.id||isDemo)&&x.status==="Manager Review"?` <button class="row-actions" data-action="finalize-appraisal" data-id="${esc(x.id)}">Finalize</button>`:""}${x.employee_id===state.profile?.employee_id&&x.status!=="Finalized"?` <button class="row-actions" data-action="self-assessment" data-id="${esc(x.id)}">Self-assess</button>`:""}${x.employee_id===state.profile?.employee_id&&x.status==="Finalized"&&!x.employee_acknowledged?` <button class="row-actions" data-action="ack-appraisal" data-id="${esc(x.id)}">Acknowledge</button>`:""}</td></tr>`).join("");
 const actions=`${isHr?`<button class="btn btn-outline" data-action="add-criterion">＋ Criterion</button><button class="btn btn-outline" data-action="add-appraisal-period">＋ Period</button>`:""}${canManage?`<button class="btn btn-primary" data-action="create-appraisal">＋ Create appraisal</button>`:""}`;
 return `${pageHeader("Performance appraisal","Set review periods, define weighted criteria, assess performance and track development.",actions)}<div class="notice">Ratings use a 1–5 scale. Criterion weights are percentage values and are normalized when calculating the overall score. Finalized appraisals are locked from further scoring.</div><div class="panel"><div class="panel-head"><h4>Appraisal periods</h4></div>${table(["Period","Dates","Status"],periods,"No appraisal periods configured.")}</div><div class="panel"><div class="panel-head"><h4>Performance criteria</h4><span>Active weights</span></div>${table(["Criterion","Weight","Status"],criteria,"No active criteria configured.")}</div><div class="panel"><div class="panel-head"><h4>Employee appraisals</h4></div>${table(["Employee","Period","Overall score","Status","Action"],appraisals,"No appraisals have been created.")}</div>`;
}
function payroll(){const canManage=["administrator","payroll"].includes(state.profile?.role)||isDemo;const rows=(state.data.payroll||[]).map(x=>`<tr><td>${person(x.employee_name)}</td><td>${esc(x.period)}</td><td>${money(x.basic)}</td><td>${money(x.allowances)}</td><td>${money(x.earnings)}</td><td>${money(x.employee_ssnit)}</td><td>${money(x.paye)}</td><td>${money(x.employer_pension)}</td><td>${money(x.deductions)}</td><td><strong>${money(x.net)}</strong></td><td>${badge(x.status)}</td></tr>`).join("");const actions=canManage?`<button class="btn btn-outline" data-action="add-payroll-component">＋ Salary component</button><button class="btn btn-outline" data-action="approve-payroll">Approve period</button><button class="btn btn-outline" data-action="mark-payroll-paid">Mark paid</button><button class="btn btn-primary" data-action="generate-payroll">Generate payroll</button>`:"";return `${pageHeader("Payroll","Generate monthly payroll, review statutory deductions and manage approvals.",actions)}<div class="notice">Payroll generation uses configurable statutory settings and effective-dated PAYE bands. Employee SSNIT is deducted from net pay; employer pension is an additional employer cost. Confirm rates, reliefs and statutory rules with your payroll adviser before production.</div>${table(["Employee","Period","Basic","Allowances","Gross","Employee SSNIT","PAYE","Employer pension","Total deductions","Net pay","Status"],rows,"No payroll records. Generate a draft payroll period to begin.")}`}
