 return `${pageHeader("Reports & analytics","Export operational data available to your role.",`<button class="btn btn-outline" data-action="refresh">↻ Refresh</button>`)}<div class="report-grid">${allowed.map(([title,key,desc])=>{const rows=state.data[key]||[];return `<div class="report-card"><h4>${esc(title)}</h4><p>${esc(desc)}. ${rows.length} record(s) available.</p><button class="btn btn-outline" data-action="export" data-report="${esc(key)}" ${rows.length?"":"disabled"}>Export CSV</button></div>`}).join("")}</div>`
